:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --primary: #6c5ce7;
  --primary-hover: #7d6ff0;
  --accent: #00cec9;
  --text: #f0f0f5;
  --text-muted: #a0a0b0;
  --border: #3a3a55;
  --danger: #e74c3c;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text);
}

#score {
  color: var(--accent);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  overflow: hidden;
  border: 2px solid var(--border);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  background: #14141f;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(20, 20, 31, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  text-align: center;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  max-width: 320px;
}

.overlay-content h2 {
  font-size: 1.4rem;
  color: var(--accent);
}

.overlay-content p {
  font-size: 1rem;
  color: var(--text-muted);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--card);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
  min-width: 100px;
}

.btn:hover {
  background: var(--border);
  border-color: var(--text-muted);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.hint {
  font-size: 0.9rem;
  color: var(--text-muted);
  text-align: center;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.95rem;
    min-width: 80px;
  }
}

(function () {
  'use strict';

  // --- Configuration ---
  const GRID_SIZE = 20;          // number of cells per row/col
  const CELL_SIZE = 20;          // pixels per cell (canvas 400x400)
  const INITIAL_SPEED = 150;     // ms per tick
  const SPEED_INCREMENT = 2;     // ms faster per food eaten
  const MIN_SPEED = 70;

  // --- DOM Elements ---
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreSpan = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayBtn = document.getElementById('overlayBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  // --- Game State ---
  let snake = [];
  let direction = { x: 0, y: 0 };
  let nextDirection = { x: 0, y: 0 };
  let food = { x: 0, y: 0 };
  let score = 0;
  let speed = INITIAL_SPEED;
  let gameState = 'paused'; // 'paused' | 'running' | 'gameover'
  let loopId = null;
  let hasStarted = false; // whether the game has ever started (for initial overlay)

  // --- Initialization ---
  function resetGame() {
    snake = [
      { x: 10, y: 10 },
      { x: 9, y: 10 },
      { x: 8, y: 10 }
    ];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    speed = INITIAL_SPEED;
    scoreSpan.textContent = '0';
    placeFood();
    draw();
  }

  function placeFood() {
    let attempts = 0;
    do {
      food = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
      attempts++;
    } while (snake.some(s => s.x === food.x && s.y === food.y) && attempts < 500);
  }

  // --- Drawing ---
  function draw() {
    // Clear board
    ctx.fillStyle = '#14141f';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines (subtle)
    ctx.strokeStyle = '#1e1e2f';
    ctx.lineWidth = 1;
    for (let i = 0; i <= GRID_SIZE; i++) {
      const pos = i * CELL_SIZE + 0.5;
      ctx.beginPath();
      ctx.moveTo(pos, 0);
      ctx.lineTo(pos, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, pos);
      ctx.lineTo(canvas.width, pos);
      ctx.stroke();
    }

    // Draw food
    ctx.fillStyle = '#e74c3c';
    ctx.fillRect(food.x * CELL_SIZE + 2, food.y * CELL_SIZE + 2, CELL_SIZE - 4, CELL_SIZE - 4);

    // Draw snake
    snake.forEach((segment, index) => {
      if (index === 0) {
        ctx.fillStyle = '#00cec9'; // head
      } else {
        ctx.fillStyle = '#6c5ce7'; // body
      }
      ctx.fillRect(segment.x * CELL_SIZE + 1, segment.y * CELL_SIZE + 1, CELL_SIZE - 2, CELL_SIZE - 2);
    });
  }

  // --- Game Loop ---
  function tick() {
    if (gameState !== 'running') return;

    // Apply queued direction
    direction = { ...nextDirection };

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    // Wall collision
    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      endGame();
      return;
    }

    // Self collision
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    // Food eaten?
    if (head.x === food.x && head.y === food.y) {
      score++;
      scoreSpan.textContent = score;
      speed = Math.max(MIN_SPEED, speed - SPEED_INCREMENT);
      placeFood();
      restartLoop();
    } else {
      snake.pop();
    }

    draw();
  }

  function startLoop() {
    stopLoop();
    loopId = setInterval(tick, speed);
  }

  function stopLoop() {
    if (loopId !== null) {
      clearInterval(loopId);
      loopId = null;
    }
  }

  function restartLoop() {
    if (gameState === 'running') {
      startLoop();
    }
  }

  // --- State Transitions ---
  function startGame() {
    if (gameState === 'running') return;
    if (gameState === 'gameover') {
      resetGame();
    }
    gameState = 'running';
    hasStarted = true;
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
    startLoop();
  }

  function pauseGame() {
    if (gameState !== 'running') return;
    gameState = 'paused';
    stopLoop();
    showOverlay('Paused', 'Press <strong>Resume</strong> or <strong>Space</strong> to continue.', 'Resume');
    pauseBtn.textContent = 'Resume';
    pauseBtn.setAttribute('aria-label', 'Resume game');
  }

  function resumeGame() {
    if (gameState !== 'paused') return;
    gameState = 'running';
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
    startLoop();
  }

  function endGame() {
    gameState = 'gameover';
    stopLoop();
    showOverlay('Game Over', `Your score: <strong>${score}</strong><br>Press <strong>Restart</strong> or <strong>Space</strong> to play again.`, 'Restart');
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
  }

  function restartGame() {
    stopLoop();
    gameState = 'paused';
    hasStarted = true;
    resetGame();
    showOverlay('Ready', 'Press <strong>Start</strong> or <strong>Space</strong> to begin.', 'Start');
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
  }

  // --- Overlay Helpers ---
  function showOverlay(title, html, btnText) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = html;
    overlayBtn.textContent = btnText;
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  // --- Event Listeners ---
  document.addEventListener('keydown', (e) => {
    const key = e.key;

    // Prevent arrow keys from scrolling
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(key)) {
      e.preventDefault();
    }

    // Space toggles start/pause/resume/restart
    if (key === ' ') {
      if (gameState === 'running') {
        pauseGame();
      } else if (gameState === 'paused') {
        if (!hasStarted) startGame();
        else resumeGame();
      } else if (gameState === 'gameover') {
        restartGame();
        startGame();
      }
      return;
    }

    // Arrow keys change direction (only when running)
    if (gameState === 'running') {
      if (key === 'ArrowUp' && direction.y === 0) {
        nextDirection = { x: 0, y: -1 };
      } else if (key === 'ArrowDown' && direction.y === 0) {
        nextDirection = { x: 0, y: 1 };
      } else if (key === 'ArrowLeft' && direction.x === 0) {
        nextDirection = { x: -1, y: 0 };
      } else if (key === 'ArrowRight' && direction.x === 0) {
        nextDirection = { x: 1, y: 0 };
      }
    }
  });

  pauseBtn.addEventListener('click', () => {
    if (gameState === 'running') {
      pauseGame();
    } else if (gameState === 'paused') {
      if (!hasStarted) startGame();
      else resumeGame();
    }
  });

  restartBtn.addEventListener('click', () => {
    restartGame();
  });

  overlayBtn.addEventListener('click', () => {
    if (gameState === 'running') {
      pauseGame();
    } else if (gameState === 'paused') {
      if (!hasStarted) startGame();
      else resumeGame();
    } else if (gameState === 'gameover') {
      restartGame();
      startGame();
    }
  });

  // --- Boot ---
  resetGame();
  // Start paused with instructions (already shown by default overlay)
})();
